import { test, expect } from '@playwright/test';

test.describe('Request Timeout Error Handling', () => {
  let testServerUrl: string;

  test.beforeEach(async ({ page }) => {
    testServerUrl = 'http://localhost:3000';
    await page.goto(testServerUrl);
  });

  test('should display timeout error when request exceeds 10 seconds', async ({ page }) => {
    // Set up a route that delays response beyond 10 seconds
    await page.route('**/api/slow-endpoint', async (route) => {
      // Delay the response by 11 seconds to exceed the 10 second timeout
      await new Promise(resolve => setTimeout(resolve, 11000));
      await route.continue();
    });

    // Click button to trigger the slow request
    const triggerButton = page.getByRole('button', { name: /trigger slow request/i });
    await triggerButton.click();

    // Wait for timeout error message to appear
    const errorMessage = page.getByText(/request timeout|took longer than 10 seconds|timeout error/i);
    await expect(errorMessage).toBeVisible({ timeout: 15000 });

    // Verify error message contains relevant information
    await expect(errorMessage).toContainText(/timeout|10 seconds/i);
  });

  test('should not display timeout error for requests completing within 10 seconds', async ({ page }) => {
    // Set up a route that responds quickly
    await page.route('**/api/fast-endpoint', async (route) => {
      // Delay the response by 2 seconds (within the 10 second timeout)
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    // Click button to trigger the fast request
    const triggerButton = page.getByRole('button', { name: /trigger fast request/i });
    await triggerButton.click();

    // Wait for success message to appear
    const successMessage = page.getByText(/success|request completed|data loaded/i);
    await expect(successMessage).toBeVisible({ timeout: 5000 });

    // Verify no timeout error is displayed
    const errorMessage = page.getByText(/request timeout|took longer than 10 seconds|timeout error/i);
    await expect(errorMessage).not.toBeVisible();
  });

  test('should allow user to retry after timeout error', async ({ page }) => {
    // First request that times out
    await page.route('**/api/slow-endpoint', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 11000));
      await route.continue();
    });

    const triggerButton = page.getByRole('button', { name: /trigger slow request/i });
    await triggerButton.click();

    // Wait for timeout error
    const errorMessage = page.getByText(/request timeout|took longer than 10 seconds|timeout error/i);
    await expect(errorMessage).toBeVisible({ timeout: 15000 });

    // Unroute the slow endpoint and set up a fast one
    await page.unroute('**/api/slow-endpoint');
    await page.route('**/api/slow-endpoint', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    // Click retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await retryButton.click();

    // Verify success message appears after retry
    const successMessage = page.getByText(/success|request completed|data loaded/i);
    await expect(successMessage).toBeVisible({ timeout: 5000 });

    // Verify timeout error is no longer visible
    await expect(errorMessage).not.toBeVisible();
  });

  test('should display timeout error with appropriate styling', async ({ page }) => {
    // Set up a route that delays response
    await page.route('**/api/slow-endpoint', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 11000));
      await route.continue();
    });

    // Trigger the slow request
    const triggerButton = page.getByRole('button', { name: /trigger slow request/i });
    await triggerButton.click();

    // Wait for error message
    const errorMessage = page.getByText(/request timeout|took longer than 10 seconds|timeout error/i);
    await expect(errorMessage).toBeVisible({ timeout: 15000 });

    // Verify error styling (should have error class or styling)
    const errorContainer = errorMessage.locator('..');
    await expect(errorContainer).toHaveClass(/error|alert-error|danger/i);

    // Verify error message is accessible
    await expect(errorMessage).toHaveAttribute('role', /alert|status/i);
  });
});
